using Full.NET.Data.Abstractions;

namespace Full.NET.Modules.Ai.Persistence;

/// <summary>固定索引输入片段；人工修订只从 AI 权威头取得，不能由请求参数伪造。</summary>
internal static class AiKnowledgeIndexCorrectionSql
{
    // 不更改版本或时间，只取得文档根排他锁；MySQL 自有连接策略使用 matched-rows 语义。
    private const string Lock = "UPDATE fn_ai_knowledge_document SET Version=Version WHERE Id=@DocumentId AND KnowledgeBaseId=@KnowledgeBaseId AND Version=@DocumentVersion AND IsDeleted=0 AND EXISTS (SELECT 1 FROM fn_ai_knowledge_base AS knowledge WHERE knowledge.Id=@KnowledgeBaseId AND knowledge.OwnerUserId=@OwnerUserId AND knowledge.Version=@KnowledgeBaseVersion AND knowledge.IsEnabled=1 AND ";
    internal static readonly SqlStatement LockHost = new("ai.knowledge_index_correction.lock_host", Lock + "knowledge.TenantId IS NULL)", SqlDataScope.HostOnly);
    internal static readonly SqlStatement LockTenant = new("ai.knowledge_index_correction.lock_tenant", Lock + "knowledge.TenantId=@TenantId)", SqlDataScope.TenantRequired, SqlTenantBinding.CurrentTenantId);
    internal const string Columns = "CorrectionSourceId,CorrectionRevisionId,CorrectionHeadVersion,CorrectionSourceHash,CorrectionPayloadHash";
    internal const string Joins = " LEFT JOIN fn_ai_knowledge_correction_head AS correction_input ON correction_input.Id=version.Id"
        + " LEFT JOIN fn_ai_knowledge_correction_source AS correction_source ON correction_source.Id=correction_input.SourceId AND correction_source.VersionId=version.Id"
        + " LEFT JOIN fn_ai_knowledge_correction_revision AS correction_revision ON correction_revision.Id=correction_input.RevisionId AND correction_revision.SourceId=correction_source.Id AND correction_revision.VersionId=version.Id";
    internal const string Values = "CASE WHEN correction_input.RevisionId IS NULL THEN NULL ELSE correction_input.SourceId END,correction_input.RevisionId,CASE WHEN correction_input.RevisionId IS NULL THEN NULL ELSE correction_input.Version END,CASE WHEN correction_input.RevisionId IS NULL THEN NULL ELSE correction_source.SourceHash END,correction_revision.PayloadHash";
    internal const string Available = " AND (correction_input.Id IS NULL OR (correction_input.RevisionId IS NULL AND correction_input.Version=0) OR (correction_input.RevisionId IS NOT NULL AND correction_input.Version>0 AND correction_source.CleanupState=0 AND correction_revision.CleanupState=0 AND correction_revision.HeadVersion=correction_input.Version AND correction_source.FileHash=version.ContentHash))";
    internal const string Group = ",correction_input.SourceId,correction_input.RevisionId,correction_input.Version,correction_source.SourceHash,correction_revision.PayloadHash";
    internal const string DispatchColumns = "fn_ai_knowledge_index_task.CorrectionSourceId,fn_ai_knowledge_index_task.CorrectionRevisionId,fn_ai_knowledge_index_task.CorrectionHeadVersion,fn_ai_knowledge_index_task.CorrectionSourceHash,fn_ai_knowledge_index_task.CorrectionPayloadHash";
    internal const string AuthorityColumns = "task.CorrectionSourceId,task.CorrectionRevisionId,task.CorrectionHeadVersion,task.CorrectionSourceHash,task.CorrectionPayloadHash";
    // 自动输入不能在人工头已经存在时降级为原文；人工输入始终比较原冻结身份和清理状态。
    internal const string Live = " AND ((fn_ai_knowledge_index_task.CorrectionSourceId IS NULL AND fn_ai_knowledge_index_task.CorrectionRevisionId IS NULL AND fn_ai_knowledge_index_task.CorrectionHeadVersion IS NULL AND fn_ai_knowledge_index_task.CorrectionSourceHash IS NULL AND fn_ai_knowledge_index_task.CorrectionPayloadHash IS NULL AND NOT EXISTS (SELECT 1 FROM fn_ai_knowledge_correction_head AS correction_current WHERE correction_current.Id=fn_ai_knowledge_index_task.VersionId AND (correction_current.Version<>0 OR correction_current.RevisionId IS NOT NULL))) OR EXISTS (SELECT 1 FROM fn_ai_knowledge_correction_head AS correction_current INNER JOIN fn_ai_knowledge_correction_source AS correction_origin ON correction_origin.Id=correction_current.SourceId AND correction_origin.VersionId=correction_current.Id INNER JOIN fn_ai_knowledge_correction_revision AS correction_saved ON correction_saved.Id=correction_current.RevisionId AND correction_saved.SourceId=correction_origin.Id AND correction_saved.VersionId=correction_current.Id WHERE correction_current.Id=fn_ai_knowledge_index_task.VersionId AND correction_current.SourceId=fn_ai_knowledge_index_task.CorrectionSourceId AND correction_current.RevisionId=fn_ai_knowledge_index_task.CorrectionRevisionId AND correction_current.Version=fn_ai_knowledge_index_task.CorrectionHeadVersion AND correction_current.Version>0 AND correction_saved.HeadVersion=correction_current.Version AND correction_origin.SourceHash=fn_ai_knowledge_index_task.CorrectionSourceHash AND correction_saved.PayloadHash=fn_ai_knowledge_index_task.CorrectionPayloadHash AND correction_origin.CleanupState=0 AND correction_saved.CleanupState=0))";
}
